// Chuyển thời gian từ Meta về định dạng ISO để lưu vào Notion.
function toIsoDate(value, fallback = Date.now()) {
  if (value !== undefined && value !== null && value !== '') {
    const numericValue = Number(value);

    if (Number.isFinite(numericValue)) {
      // Meta có thể gửi Unix timestamp theo giây hoặc mili-giây.
      const milliseconds =
        numericValue < 1_000_000_000_000
          ? numericValue * 1000
          : numericValue;

      return new Date(milliseconds).toISOString();
    }

    const parsedDate = new Date(value);

    if (!Number.isNaN(parsedDate.getTime())) {
      return parsedDate.toISOString();
    }
  }

  return new Date(fallback).toISOString();
}

const results = [];

// Đọc toàn bộ item đi vào Code node.
for (const inputItem of $input.all()) {
  const body = inputItem.json.body ?? inputItem.json;

  const entries = Array.isArray(body.entry)
    ? body.entry
    : [];

  for (const entry of entries) {
    const pageId = String(entry.id ?? '');
    const entryTime = entry.time ?? Date.now();

    /*
     * PHẦN 1: FACEBOOK MESSENGER INBOX
     */
    const messagingEvents = Array.isArray(entry.messaging)
      ? entry.messaging
      : [];

    for (const event of messagingEvents) {
      const message = event.message ?? {};

      // Bỏ tin nhắn do chính Page hoặc bot gửi ra.
      if (message.is_echo === true) {
        continue;
      }

      // Xác định nội dung tin nhắn: chữ, sticker, ảnh, video, audio hoặc file.
      let messageText = '';
      let imageUrl = '';

      if (message.text) {
        messageText = String(message.text).trim();
      } else if (Array.isArray(message.attachments) && message.attachments.length > 0) {
        const attachment = message.attachments[0];
        const isSticker = Boolean(attachment.payload?.sticker_id);

        if (isSticker) {
          messageText = '[Khách gửi sticker]';
        } else if (attachment.type === 'image') {
          messageText = '[Khách gửi hình ảnh]';
          imageUrl = attachment.payload?.url ?? '';
        } else if (attachment.type === 'video') {
          messageText = '[Khách gửi video]';
        } else if (attachment.type === 'audio') {
          messageText = '[Khách gửi tin nhắn thoại]';
        } else if (attachment.type === 'file') {
          messageText = '[Khách gửi file đính kèm]';
        } else {
          messageText = '[Khách gửi nội dung không phải văn bản]';
        }
      } else {
        // Không có chữ lẫn tệp đính kèm (vd: quick reply, postback...) - bỏ qua.
        continue;
      }

      const senderId = String(event.sender?.id ?? '');

      const recipientPageId = String(
        event.recipient?.id ??
        pageId
      );

      if (!senderId) {
        continue;
      }

      const timestamp = toIsoDate(
        event.timestamp,
        entryTime
      );

      const messageId = String(
        message.mid ??
        `message:${senderId}:${event.timestamp ?? entryTime}`
      );

      results.push({
        json: {
          source: 'Facebook',
          interaction_type: 'Inbox',
          event_type: 'message',

          meta_user_id: senderId,
          customer_name: '',

          page_id: recipientPageId,
          post_id: '',
          parent_id: '',

          message_id: messageId,
          message_text: messageText,
          image_url: imageUrl,

          timestamp,

          lead_key: `facebook:inbox:${senderId}`,
        },
      });
    }

    /*
     * PHẦN 2: BÍNH LUẬN FACEBOOK PAGE
     */
    const changes = Array.isArray(entry.changes)
      ? entry.changes
      : [];

    for (const change of changes) {
      const field = change.field ?? '';
      const value = change.value ?? {};

      const isNewComment =
        field === 'feed' &&
        value.item === 'comment' &&
        value.verb === 'add';

      if (!isNewComment) {
        continue;
      }

      const senderId = String(
        value.from?.id ?? ''
      );

      const senderName = String(
        value.from?.name ?? ''
      );

      const commentText = String(
        value.message ?? ''
      ).trim();

      // Không có người gửi hoặc không có nội dung thì bỏ qua.
      if (!senderId || !commentText) {
        continue;
      }

      // Bỏ bình luận do chính Page đăng để tránh bot xử lý lại.
      if (senderId === pageId) {
        continue;
      }

      const commentId = String(
        value.comment_id ??
        value.id ??
        `comment:${senderId}:${entryTime}`
      );

      const postId = String(
        value.post_id ?? ''
      );

      const parentId = String(
        value.parent_id ?? ''
      );

      results.push({
        json: {
          source: 'Facebook',
          interaction_type: 'Comment',
          event_type: 'comment',

          meta_user_id: senderId,
          customer_name: senderName,

          page_id: pageId,
          post_id: postId,
          parent_id: parentId,

          message_id: commentId,
          message_text: commentText,

          timestamp: toIsoDate(
            value.created_time,
            entryTime
          ),

          lead_key: `facebook:comment:${senderId}`,
        },
      });
    }
  }
}

return results;

const page = $input.first().json;
const props = page.properties || {};
const oldBuffer = props['Bộ đệm tin nhắn']?.rich_text?.[0]?.plain_text || '';
const oldImageUrl = props['URL ảnh gần nhất\t']?.rich_text?.[0]?.plain_text || '';
const lastMidsRaw = props['Mid tin nhắn cuối']?.rich_text?.[0]?.plain_text || '';
const lastMids = lastMidsRaw ? lastMidsRaw.split('\n').filter(Boolean) : [];
const currentMid = $('Code - Chuẩn hóa Meta Event').first().json.message_id;
const newMessage = $('Code - Chuẩn hóa Meta Event').first().json.message_text;
const newImageUrl = $('Code - Chuẩn hóa Meta Event').first().json.image_url || '';

const isDuplicate = lastMids.includes(currentMid);

const mergedBuffer = isDuplicate
  ? oldBuffer
  : (oldBuffer ? `${oldBuffer}\n${newMessage}` : newMessage);
const mergedImageUrl = newImageUrl || oldImageUrl;
const updatedMids = isDuplicate ? lastMids : [...lastMids, currentMid].slice(-20);

return [{
  json: {
    pageId: page.id,
    mergedBuffer,
    imageUrl: mergedImageUrl,
    ts: new Date().toISOString(),
    isDuplicate,
    midList: updatedMids.join('\n'),
  },
}];

